ALTER TABLE `SRO_SHARD`.`GAMEPLAY_MOB_RATES`
    ADD COLUMN `WINTER_DROP_CHANCE_BP` INT UNSIGNED NOT NULL DEFAULT 5000 AFTER `BERSERK_DURATION_PER_POINT_MS`,
    ADD COLUMN `WINTER_DROP_ITEM_COUNT` INT UNSIGNED NOT NULL DEFAULT 1 AFTER `WINTER_DROP_CHANCE_BP`,
    ADD COLUMN `BATTLE_ARENA_TICKET_RATE` INT UNSIGNED NOT NULL DEFAULT 0 AFTER `WINTER_DROP_ITEM_COUNT`,
    ADD COLUMN `BATTLE_ARENA_WORLD_IDS` VARCHAR(255) NOT NULL DEFAULT '42,43,44,45,46,47,48,49,50' AFTER `BATTLE_ARENA_TICKET_RATE`,
    ADD COLUMN `HWAN_BASE_CHANCE_BP` INT UNSIGNED NOT NULL DEFAULT 800 AFTER `BATTLE_ARENA_WORLD_IDS`,
    ADD COLUMN `HWAN_OVERLEVEL_GRACE` INT UNSIGNED NOT NULL DEFAULT 5 AFTER `HWAN_BASE_CHANCE_BP`,
    ADD COLUMN `HWAN_PENALTY_PER_LEVEL_BP` INT UNSIGNED NOT NULL DEFAULT 25 AFTER `HWAN_OVERLEVEL_GRACE`,
    ADD COLUMN `HWAN_MIN_CHANCE_BP` INT UNSIGNED NOT NULL DEFAULT 25 AFTER `HWAN_PENALTY_PER_LEVEL_BP`,
    ADD COLUMN `HWAN_GIANT_MULTIPLIER` INT UNSIGNED NOT NULL DEFAULT 5 AFTER `HWAN_MIN_CHANCE_BP`,
    ADD COLUMN `HWAN_ELITE_MULTIPLIER` INT UNSIGNED NOT NULL DEFAULT 2 AFTER `HWAN_GIANT_MULTIPLIER`,
    ADD COLUMN `SERVER_MAX_LEVEL` INT UNSIGNED NOT NULL DEFAULT 110 AFTER `HWAN_ELITE_MULTIPLIER`,
    ADD COLUMN `EU_MASTERY_MAX_TOTAL` INT UNSIGNED NOT NULL DEFAULT 240 AFTER `SERVER_MAX_LEVEL`,
    ADD COLUMN `EU_MASTERY_POINTS_PER_LEVEL` INT UNSIGNED NOT NULL DEFAULT 2 AFTER `EU_MASTERY_MAX_TOTAL`,
    ADD COLUMN `CH_MASTERY_MAX_TOTAL` INT UNSIGNED NOT NULL DEFAULT 330 AFTER `EU_MASTERY_POINTS_PER_LEVEL`,
    ADD COLUMN `CH_MASTERY_POINTS_PER_LEVEL` INT UNSIGNED NOT NULL DEFAULT 3 AFTER `CH_MASTERY_MAX_TOTAL`,
    ADD COLUMN `MAX_SPEED_EFFECT_MINUTES` INT UNSIGNED NOT NULL DEFAULT 1440 AFTER `CH_MASTERY_POINTS_PER_LEVEL`,
    ADD CONSTRAINT `chk_runtime_event_policy` CHECK (`WINTER_DROP_CHANCE_BP` <= 10000 AND `WINTER_DROP_ITEM_COUNT` > 0 AND `BATTLE_ARENA_TICKET_RATE` <= 100),
    ADD CONSTRAINT `chk_runtime_hwan_policy` CHECK (`HWAN_BASE_CHANCE_BP` <= 10000 AND `HWAN_PENALTY_PER_LEVEL_BP` <= 10000 AND `HWAN_MIN_CHANCE_BP` <= 10000 AND `HWAN_GIANT_MULTIPLIER` > 0 AND `HWAN_ELITE_MULTIPLIER` > 0),
    ADD CONSTRAINT `chk_runtime_progression_policy` CHECK (`SERVER_MAX_LEVEL` BETWEEN 1 AND 255 AND `EU_MASTERY_MAX_TOTAL` > 0 AND `EU_MASTERY_POINTS_PER_LEVEL` > 0 AND `CH_MASTERY_MAX_TOTAL` > 0 AND `CH_MASTERY_POINTS_PER_LEVEL` > 0 AND `MAX_SPEED_EFFECT_MINUTES` > 0);
